INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1378544-engl003', 'stk-kfupm76', 'ENGL 003', 'info', '{"desc": "مع ان الكورس غبي\n\nبس انصحك بالفوكااااااب و اغلب الاسئلة تكون فوكاب\n\nراح اقلك على طريقة هيا صعبه شويه لكن جدا مفيده\n\n- احفظ جميع الفوكاب الي باللسته\n-حاول انك كل يوم تذاكرلك قطعه في الريدينغ اكسبلورر بحيث انك تحط تحت كل الكلمات الي ماتعرفها وتترجمها وتحفظها\n- الليسننق كله من الهيدواي فحاول انك تاخذ ملفات الليسننق من المدرس وتسمع جميع الليسننق قبل الاختبار او فالوقت الي يناسبك وصدقني راح تحل بعض الاسئلة في الليسننق من دون ان تسمع كامل السؤال لانك قد سمعته من قبل وفاهمه زيين\n- لا تنسى تركز في اختيارات اسئلة الليسننق لانها خبيثه لانك حتصادف بعض الاحيان ان كل الخيارات الاربعه صح لكن الكوردينتور يلعب على القرامر فيها فيخليك تلخبط (( فحاول تركز على كل الخيارات))\n- بالنسبه للقرامر حاول انك تفهمه من اخر الكتاب واذا حسيت انو عندك مشكله في قاعده حاول انك تبحث عن كويزز لها فيا النت\n- اذكرك مرره ثانيه ترا الاختيارات دائما خبيثثثثثثثثثه فحاول تركز قد م تقدر\n\nطبعا حاول انك تنظم وقتك وما تضغط نفسك قبل الاختبارات وتطبق هالخطوات واضمنلك انك ما تجيب اقل من b ان شاءالله\n\nفالك البروموشن ان شاءالله …", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/162051/15", "user": "kfupm76", "ts": 1402263106000, "tid": 162051, "pn": 15}}', 1402263106000, 1794837144, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1378776-engl003', 'stk-ab1010', 'ENGL 003', 'info', '{"desc": "انا سمعة ان غيروا النظام الحين في 03 و صار الفوكاب من الريدنق بس الحمر و الزرق\nو الهيدواي الديبارت منت بيعطينا لسته هذا الاسبوع ان شاء الله صح كلامهم\n\nاللسنق اموره سهله ان شاء الله اذا كان نفس الكلام الي قاله الاخ فوق\n\nبس الجرامر سالفته سالفة ويا الكتاب الهيدواي صعب فيهم الجرامر منه\n\nو شكرا لك ع الرد يعطي الف عافية 🥰 ❤️", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/162051/17", "user": "Ab1010", "ts": 1402326080000, "tid": 162051, "pn": 17}}', 1402326080000, 1794837144, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1206818-engl003', 'stk-e-asb', 'ENGL 003', 'info', '{"desc": "اخي الكريم مدرسنا قلنا شيء ثاني عن الي انت كتبتو … فمدري هل انت متأكد هذه الوحدات داخله معنا في الكويز\n\nالكويز على حسب كلام مدرسنا\n\nاللسننق : الوحدة الثالثة\n\nالريدنق: الثالثة والرابعة\n\nالفوكاب: جميع ما اخذناه من الوايت بووك من الوحدة الاولى الى الرابعة\n\nالقرامر: قرامر من التوفل الي مرفوع على البلاك بورد الملف الاول فقط\n\n🌹", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/eng-03-quiz/142671/5", "user": "e-asb", "ts": 1365290171000, "tid": 142671, "pn": 5}}', 1365290171000, 1794837144, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1114564-engl003', 'stk-saffa7', 'ENGL 003', 'info', '{"desc": "السلام عليكم ورحمة الله وبركاته\n\nكيف الحال ياشباب الحمد لله بخير\n\nالقصة ومافيها اني رسبت في الانجليزي 03 ويوم طلعت النتيجة وشفتها دخلت في حالة نفسية سيئة للغاية وماكنت ابغى اي احد يكلمني عن المادة في العموم وبعد فترة حبيت اسوي موضوع في المنتدى عن الشباب الراسبين اللي زيي عشان نحمس بعض لكن قلت خليها بعدين مو لازم دحين\nالمهم اليوم في صلاة الجمعة كان الشيخ يتكلم عن (حسن الظن بالله جل وعلا والثقة به) لمن قالها افتكرت ليش ماخلي اموري كلها لله عز وجل وباذن الله مايخيب املي المهم اليوم في صلاة المغرب جلست ادعي في السجود انه ربي ينجحني في الانجليزي وانا راسب فيه وقد طلعت الدرجة خلاص يعني مافي امل تتغير الا باذن الله وبعد الصلاة المغرب بعد الدعاء تمام بـ 10 دقائق والله ياشباب بدون مبالغة والله يعلم صدقي دق علي مشرف الانجليزي حق السنة التحضيرية قالي انت الطالب بسام قلت له ايه قالي انت شفت درجتك صح قلت ايه قالي راسب قلت يلا هذا رجع يذكرني بالماضي الحزين مرة ثانية قلي حصل خطا في الكمبيوتر ولم يحسب لك بعض الدرجات اللي تستحقها يوم قال الكلمة هاذي وانا والله مادري وين الله حطني الرجال يتكلم وانا ماعاد استوعب ايش يقول من الفرحة المهم قلت له طيب ايش الدرجة قلي انت c ونجحت الحمد لله على كل حال ولا ننسى دائما نتوكل على الله في جميع امورنا\nاخواني اللي رسبوا لا تفقدوا الامل راجع المدرس خليه يعدل لكم او يدفكم او اي شيء ولا تنسوا دعاء الله عز وجل دائما وابدا\nهذا القصة اللي صارت لي وحبيت اقولها لكم من باب التذكير بحسن الظن بالله تعالى\nوالله لا يعلم الفرحة اللي في قلبي الا هو … والحمد لله والشكر لله\nتقبلوا تحياتي محبكم بسام", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/134388/1", "user": "SaFFa7", "ts": 1352473842000, "tid": 134388, "pn": 1}}', 1352473842000, 1794837144, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-sultan_salman_1419-engl003', 'stk-sultan_salman_1419', 'ENGL 003', 'doc', '{"docs": [{"id": "stk-dr-f68525", "n": "Dr. Denis Christopher Kearney", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Engl03 … Term 162\n\nالتحضير : ناسي متى … ولكنه متساهل في الغيابات بشكل كبير جدا\n\nطريقة الشرح : ممتاز … في القرامر ممتاز … في اللسننق جيد … في الريدينق جيد جدا … وممتاز في الرايتينق\n\nالكويزات : كان يعطينا أوراق كثيرة جدا ولكن فيها من الفائدة الشيء الكثير\n\nالمياجر: مافيه\n\nالفاينلات : مافيه\n\nالقريد النهائي: A+\n\nالصوت: واضح\n\nإضافات : أستاذ خلوق ومحترم … يطقطق في بعض الاحيان على الطلاب اللي يجيبون درجة سيئة في البروقرس والميد … يشرح للطلاب قصص حصلت له في الماضي … يعطيك اجابات البروقرس والميد بعد الاختبار بيوم … رائع في التوفل … يفتت الكتاب الاخضر صفحة صفحة وأحيانا يجيب أسئلة من الكتاب الاحمر … لا تغيب في الحصص الاخيرة له لانه يشرح التوفل وشرحه بيساعدك على احراز درجة عالية في التوفل … يخصص بعض الحصص للرايتينق ( لو خلصت بدري يمديك تطلع بدري ) … حاول تجلس في المقدمة وتشارك عشان يتذكرك الاستاذ .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1481582-engl003", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/kearney-denis-christopher/68525/11", "user": "sultan_salman_1419", "ts": 1507563938000, "tid": 68525, "pn": 11}}]}', 1507563938000, 1794837144, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-to_be_engineer-engl003', 'stk-to_be_engineer', 'ENGL 003', 'doc', '{"docs": [{"id": "stk-dr-f68595", "n": "Dr. Sarel Van Rooy Snyman", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Eng03 -162\n\nالتحضير : حاول ما تتأخر عشان ما يطقطق عليك… حسسه انك مهتم بداية الكورس بيدلعك بنهايته (اخوكم فالله عنده 6 غيابات ما حسبها 😆).\nطريقة الشرح :اسطوري بكل ما تعنيه الكلمه… القرامر يحل معنا التمارين في الكتاب الصغير ويشرح على الاسئلة … الريدينق يخليك تقرأ القطعة بعدين يشغل المقطع الصوتي رغم انه مو مطلوب منه بعدين يقلك حل التمارين بنفسك خمس دقايق ونحلها سوا… الرايتنق بيدقق على اخطاء السبلينق وممكن يسفل فيك اذا فيه كوارث… بس خذها براحبة صدر لانه يبي مصلحتك… الليسننق يحاول يشغل لنا اغلب المقاطع الصوتيه اللي من ظهر الكتاب…الفوكاب وهذا اكثر شي يميزه ينحت الفوكاب في راسك نحت اذا شاف كلمة مفيدة يفتح صور قوقل ويفتح اليوتيوب يحاول يوصلك المعنى بأي طريقة… الفوكاب اهم شي فاللغة اذا ملكته يصير الباقي زي تركيب المكعبات .\nالكويزات :NA\nالمياجر:NA\nالفاينلات :NA\nالقريد النهائيل:A+\nالصوت: لهجة جنوب افرييقية فيها نبرة رهيبة… واضح.\nإضافات : مدرس رهيب بمعنى الكلمة 4 ساعات ودك ما تخلص … راعي استهبال وزحف … عنده مشكلة برجوله ما يقدر يتحرك كثير… عنده رشاش موية اذا انك سرحان توقع تجيك كم رشة 👏… كنت ارجع ابي اذاكر احصلني فاهم اغلب الاشياء من شرحه الرهيب …اذا حطوك عنده احمد ربك.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1492939-engl003", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/snyman-sarel-van-rooy/68595/24", "user": "To_Be_Engineer", "ts": 1527117215000, "tid": 68595, "pn": 24}}]}', 1527117215000, 1794837144, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-rapls-engl003', 'stk-rapls', 'ENGL 003', 'doc', '{"docs": [{"id": "stk-dr-f118969", "n": "Dr. Nicholas Mann", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "171 - Eng 03\n\nالتحضير : يحضر قليل والامور عنده سهالات , ما يعطي DN ابد 😏 .\n\nطريقة الشرح : شرحه جيد جدًا , يحب يسمع من الطلاب ويخليهم يتفاعلون .\n\nالكويزات : كان يعطينا تاسكات رايتنق , وتصحيحه لا بأس به .\n\nالمياجر: كومن .\n\nالفاينلات : كومن .\n\nالقريد النهائي: B+\n\nالصوت: واضح وجيد .\n\nإضافات :هو بريطاني من لندن وسافر لدول كثيرة ويحب سوالف الحضارات ويحب سوالف شكسبير وشارلوك هولمز , يموت في الشاهي كعادة البريطانيين , اخلاقه طيبة مرة وهادي وما يعصب ولا ينافخ , له تسع سنوات في الجامعة وأظنه صار شايب , لا بأس به ولكن من ناحية الشرح في أفضل منه 😁 .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1498514-engl003", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mr-mann-nicholas/118969/10", "user": "Rapls", "ts": 1535728442000, "tid": 118969, "pn": 10}}]}', 1535728442000, 1794837144, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-solid_snake1-engl003', 'stk-solid_snake1', 'ENGL 003', 'doc', '{"docs": [{"id": "stk-dr-f172424", "n": "Dr. John Baker", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ENGL-03 Term 171\n\nالتحضير : متعاون بس لاتفلها 😆\nطريقة الشرح : ممتاز بالقرامر (كان يدرسني ايرلي فقط )\nالكويزات :مافيه\nالمياجر:مافيه\nالفاينلات :مافيه\nالقريد النهائي:B+\nالواجبات: دايم يعطي واجبات لاكن مايحاسب على الأغلاط\nالصوت:جيد لاكن يفضل تجلس في الصفوف الاماميه\nإضافات : الاستاذ شرحه ممتاز بالقرامر ودايم يعطي الطلاب تمارين كثيره وصراحاً متعاون في الاوفس اور وايضا نوتاته ممتازه ويحطها بالبلاك بورد.\nعيوبه: شرحه ممل احيانا و نكته سامجه 😁", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1483105-engl003", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/john-baker/172424/5", "user": "solid_snake1", "ts": 1510160145000, "tid": 172424, "pn": 5}}]}', 1510160145000, 1794837144, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
